use super::*;
#[test]
fn original_static_stitch_keeps_prefix_and_rebases_indices() {
    let old=Rdp {indices:vec![0,2,7,12],points:vec![Vec2::new(0.0,0.0),Vec2::new(2.0,0.0),Vec2::new(7.0,0.0),Vec2::new(12.0,0.0)]};
    let next=Rdp {indices:vec![0,3,6],points:vec![Vec2::new(2.0,0.0),Vec2::new(5.0,0.0),Vec2::new(8.0,0.0)]};
    let result=old.stitch_with(1,&next);
    assert_eq!(result.indices,[0,2,5,8]);
    assert_eq!(result.points,[Vec2::new(0.0,0.0),Vec2::new(2.0,0.0),Vec2::new(5.0,0.0),Vec2::new(8.0,0.0)]);
}

